python3 -I -c "import pathlib,json; root=pathlib.Path('.session/exports'); fields=('name','conclusion','started_at','completed_at'); keep=('Routed session','Session','Pack the results','Run actions/upload-artifact@v4','Run actions/download-artifact@v4','Epilogue');
for p in sorted((root/'actions').glob('*.json')):
 d=json.loads(p.read_text()); print(p.name,{k:d[k] for k in ('id','name','conclusion','created_at','updated_at','run_attempt')});
 for j in d['jobs']:
  print('JOB',j['id'],{k:j.get(k) for k in fields});
  if j['name'] in ('session','epilogue'):
   for i,s in enumerate(j['steps']):
    if s['name'] in keep: print('STEP',i,{k:s.get(k) for k in fields})
for folder in ('reports','records'):
 for p in sorted((root/folder).glob('*.json')):
  d=json.loads(p.read_text()); print(folder,p.name,'keys',list(d)); print('shape',[(k,type(v).__name__,len(v) if isinstance(v,(dict,list)) else '') for k,v in d.items()])"

